<?php
require_once __DIR__.'/config/config.php';require_once __DIR__.'/includes/functions.php';require_login();if(!current_user_id())redirect('/login.php');
$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE order_id=? AND user_id=?');$s->execute([$id,current_user_id()]);$order=$s->fetch();if(!$order){$errorCode=404;require __DIR__.'/error.php';exit;}
$s=$pdo->prepare('SELECT oi.*,p.image,p.image_alt,p.category_id,c.category_name FROM order_items oi JOIN products p ON p.product_id=oi.product_id LEFT JOIN categories c ON c.category_id=p.category_id WHERE oi.order_id=?');$s->execute([$id]);$items=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM order_status_history WHERE order_id=? ORDER BY status_date');$s->execute([$id]);$history=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM payments WHERE order_id=?');$s->execute([$id]);$payment=$s->fetch();$delivery=latest_delivery($pdo,$id);
// Customers may cancel their own order while it is still Pending and unpaid.
$payStatus=(string)($pdo->query('SELECT payment_status FROM payments WHERE order_id='.(int)$id)->fetchColumn()?:'');
$canCancel=($order['order_status']==='Pending' && $payStatus!=='Paid');
$returnUnits=0;foreach($items as $it){$returnUnits+=(int)$it['quantity'];}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='cancel_order'){
 verify_csrf();
 try{
  if(!$canCancel)throw new UserFacingException('This order can no longer be cancelled online. Please contact the store.');
  change_order_status($pdo,$id,'Cancelled','Cancelled by customer: '.mb_substr(trim($_POST['reason']??'No reason given'),0,200),['message'=>'You cancelled order #'.$id.'.']);
  flash('Order #'.$id.' has been cancelled and the stock released.');
 }catch(Throwable $ex){flash(user_error_message($ex,'order cancel'),'error');}
 redirect('/order_detail.php?id='.$id);
}
$pageTitle='Order Details';require __DIR__.'/includes/header.php';
?>
<div class="page-head"><div><h1>Order #<?= $id ?></h1><p class="muted">Placed <?= e($order['order_date']) ?></p></div><a class="btn btn-outline" href="<?= BASE_URL ?>/my_orders.php">Back to Orders</a></div>
<?php if($canCancel): ?><form method="post" class="card u-filter-row" onsubmit="return confirm(<?= e(json_encode('Cancel order #'.$id.'? '.$returnUnits.' unit(s) across '.count($items).' item(s) go back into stock, and you cannot undo this.')) ?>)"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="cancel_order"><div class="u-grow-200"><label for="cancel-reason">Reason for cancelling (optional)</label><input id="cancel-reason" name="reason" maxlength="200"></div><button class="btn btn-danger">Cancel order</button><p class="small muted u-grow-200"><?= (int)$returnUnits ?> unit(s) return to stock.</p></form><?php endif; ?>
<div class="grid u-cols-2-1"><div class="card"><h2>Items</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><div class="cart-prod"><div class="thumb"><?= product_visual($i) ?></div><div><strong><?= e($i['product_name']) ?></strong><div class="small muted"><?= e($i['category_name']??'Hardware') ?></div></div></div></td><td><?= $i['quantity'] ?></td><td><?= money($i['unit_price']) ?></td><td><?= money($i['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="text-right">Delivery fee: <?=money($order['delivery_fee']??0)?><br><strong>Total: <?= money($order['total_amount']) ?></strong></p></div><div class="card"><h2>Order status</h2><span class="pill <?= pill_class($order['order_status']) ?>"><?= e($order['order_status']) ?></span><h3 class="u-mt-18">Delivery address</h3><div class="small"><?= delivery_block_html($order) ?></div><h3>Payment</h3><p><?= e($payment['payment_method']??'') ?><br><?= e($payment['payment_status']??'') ?></p><?php if($delivery): ?><h3>Delivery</h3><div class="delivery-box"><p><span class="pill <?= pill_class($delivery['status']) ?>"><?= e($delivery['status']) ?></span></p><p>Scheduled: <b><?= e(date('M j, Y',strtotime($delivery['scheduled_date']))) ?></b></p><?php if($delivery['driver_name']): ?><p>Driver: <b><?= e($delivery['driver_name']) ?></b><?php if($delivery['driver_phone']): ?><br><span class="small muted"><?= e($delivery['driver_phone']) ?></span><?php endif; ?></p><?php endif; ?><?php if($delivery['delivered_at']): ?><p class="small muted">Delivered <?= e($delivery['delivered_at']) ?><?php if($delivery['received_by']): ?> · received by <?= e($delivery['received_by']) ?><?php endif; ?></p><?php endif; ?><?php if($delivery['status']==='Failed'&&$delivery['failure_reason']): ?><p class="small muted">Attempt failed: <?= e($delivery['failure_reason']) ?>. We will contact you to reschedule.</p><?php endif; ?></div><?php endif; ?><a class="btn btn-outline btn-block" href="<?= BASE_URL ?>/receipt.php?order_id=<?= $id ?>">View Receipt</a></div></div>
<div class="card tracking-card u-mt-18"><h2>Order tracking</h2><?php $steps=['Pending','Confirmed','Preparing','Ready for Delivery','Out for Delivery','Completed'];$current=array_search($order['order_status'],$steps,true);if($order['order_status']==='Cancelled'):?><div class="cancelled-state">✕ Order Cancelled</div><?php else:?><div class="tracking-steps"><?php foreach($steps as $idx=>$step):$done=$current!==false&&$idx<=$current;?><div class="tracking-step <?=$done?'done':''?> <?=($current===$idx)?'current':''?>"><span><?= $done?'✓':($idx+1)?></span><b><?=e(['Ready for Delivery'=>'Ready','Out for Delivery'=>'On the way'][$step]??$step)?></b></div><?php endforeach;?></div><?php endif;?><div class="history-list"><?php foreach($history as $h):?><div class="history-entry"><span class="history-dot"></span><div><b><?=e($h['status'])?></b><small><?=e($h['status_date'])?></small><?php if(!empty($h['remarks'])):?><p><?=e($h['remarks'])?></p><?php endif;?></div></div><?php endforeach;?></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
